import{_ as r,a0 as a,w as p,s as l,ao as d,I as s,x as t,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop","title":"Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享","tag":"201408","desc":""},"relativePath":"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop.md","filePath":"[post].md"}'),u={name:"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop.md"};function m(x,n,g,f,C,L){const o=a("Link");return p(),l("div",null,[n[11]||(n[11]=d(`<h1 id="linux有问必答-如何在linux-mint-cinnamon启用桌面共享" tabindex="-1">Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享 <a class="header-anchor" href="#linux有问必答-如何在linux-mint-cinnamon启用桌面共享" aria-label="Permalink to “Linux有问必答：如何在Linux Mint Cinnamon启用桌面共享”">​</a></h1><blockquote><p><strong>问题</strong>：我试着在Linux Mint 17 Cinnamon桌面上通过Vino VNC服务器（vino-server）启用桌面共享。但是，我发现用来配置vino-server（如，共享选项，安全，通知开/关）的vino首选项工具已经不复存在了。同时，我也的Cinnamon桌面上也找不到共享菜单。我怎样才能在最新的Linux Mint 17 Cinnamon桌面上通过vino-server配置桌面共享？</p></blockquote><p>最新的Linux Mint 17 Cinnamon桌面附带了预安装用于VNC桌面共享的vino-server，但是它报告说桌面共享菜单丢失了。</p><p>一个配置vino-server并启用桌面共享的可选方式，是使用dconf-editor的图形界面。</p><p>首先安装dconf-editor：</p><pre><code>$ sudo apt-get install dconf-editor
</code></pre><p>启动dconf-editor。</p><pre><code>$ dconf-editor
</code></pre><p>在dconf-editor的左边面板中导航到“org-&gt;gnome-&gt;desktop-&gt;remote-access”，然后你将会看到各种各样的桌面共享选项。</p><p><img src="https://farm4.staticflickr.com/3916/14843965473_e68598b01b_z.jpg" alt=""></p><p>最重要的是，点击“enabled”来激活桌面远程访问。除此之外，你还可以自定义其它选项。</p><p>例如，你可以通过修改以下字段来启用VNC密码验证：</p><ul><li><strong>authentication-methods</strong>: 设置为 [&#39;vnc&#39;]</li><li><strong>vnc-password</strong>: 将你喜欢的密码修改为Base64编码的字符串。</li></ul><p>在本例中，我们选择“password”为VNC密码，它的Base64编码字符串为“cGFzc3dvcmQ=”。</p><p>你也可以选择启用其它选项：</p><ul><li>notify-on-connect: 当vino-server接收到连接请求时显示桌面通知。</li><li>prompt-enabled: 远程用户不允许通过VNC工具访问桌面，除非VNC请求被该桌面的拥有者许可。</li></ul><h3 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to “排障”">​</a></h3><ol><li><p>当启动vino-server时，我碰到了下面的错误。</p><p>** (vino-server:4280): WARNING **: The desktop sharing service is not enabled, so it should not be run.</p></li></ol><p>要启用桌面共享服务，请使用上面讲过的dconf-editor。 也可以选择运行以下命令：</p><pre><code> # gsettings set org.gnome.Vino enabled true 
</code></pre><hr>`,21)),s("p",null,[n[1]||(n[1]=t("via: ",-1)),e(o,{href:"http://ask.xmodulo.com/enable-configure-desktop-sharing-linux-mint-cinnamon-desktop.html"},{default:i(()=>[...n[0]||(n[0]=[t("http://ask.xmodulo.com/enable-configure-desktop-sharing-linux-mint-cinnamon-desktop.html",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=t("译者：",-1)),e(o,{href:"https://github.com/GOLinux"},{default:i(()=>[...n[2]||(n[2]=[t("GOLinux",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const v=r(u,[["render",m]]);export{k as __pageData,v as default};
